const crypto = require('crypto');

const decrypt = (encrypted) => {
  const key = Buffer.from($env.TOKEN_ENCRYPTION_KEY, 'base64');
  const raw = Buffer.from(encrypted, 'base64');
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, raw.subarray(0, 12));
  decipher.setAuthTag(raw.subarray(12, 28));
  return Buffer.concat([decipher.update(raw.subarray(28)), decipher.final()]).toString('utf8');
};

const asJson = (res) => (typeof res === 'string' ? JSON.parse(res) : res);

const results = [];
for (const item of $input.all()) {
  const account = item.json;
  try {
    if (!account.access_token || !account.refresh_token) {
      throw new Error('sem tokens guardados');
    }

    const tokenRes = asJson(await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://oauth2.googleapis.com/token',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: 'client_id=' + encodeURIComponent($env.GOOGLE_CLIENT_ID) + '&client_secret=' + encodeURIComponent($env.GOOGLE_CLIENT_SECRET) + '&refresh_token=' + encodeURIComponent(decrypt(account.refresh_token)) + '&grant_type=refresh_token',
    }));
    const auth = { Authorization: 'Bearer ' + tokenRes.access_token };

    const watch = asJson(await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://gmail.googleapis.com/gmail/v1/users/me/watch',
      headers: { ...auth, 'Content-Type': 'application/json' },
      body: JSON.stringify({ topicName: $env.GMAIL_PUBSUB_TOPIC, labelIds: ['INBOX'] }),
    }));

    // O ponteiro so e reposto se ja estiver invalido; um reset cego saltava mensagens por processar.
    let historyId = account.last_history_id;
    if (historyId) {
      try {
        await this.helpers.httpRequest({
          url: 'https://gmail.googleapis.com/gmail/v1/users/me/history',
          qs: { startHistoryId: historyId, maxResults: 1 },
          headers: auth,
        });
      } catch (error) {
        // So um 404 prova que o ponteiro morreu; noutro erro qualquer mantem-se, renovar o watch e o que importa aqui.
        if (error.status === 404) historyId = null;
      }
    }

    results.push({ json: {
      id: account.id,
      email_gmail: account.email_gmail,
      watch_expiration: new Date(Number(watch.expiration)).toISOString(),
      last_history_id: historyId || String(watch.historyId),
    } });
  } catch (error) {
    console.log('Renovacao falhou (' + account.email_gmail + '): ' + error.message);
  }
}
return results;
